-- ============================================================================
-- 0019_education_career.sql
--
-- Jembatan program studi / konsentrasi SMK -> profesi.
--
-- Dibutuhkan baris "Relevan dengan Program Studi" di layar Explore, dan di
-- diagram tim desain ia digambar sebagai tabel education_career yang belum
-- pernah ada di database kita.
--
-- Dua lapis, dan bedanya terekam di kolom source:
--
--   aturan_kata_kunci  jembatan yang ditulis tangan — program studi yang
--                      memuat "farmasi" mengarah ke profesi yang memuat
--                      "apoteker". relevance 90.
--   rumpun_studi       jaring pengaman: profesi dalam rumpun SOC yang sesuai
--                      rumpun studinya, diurutkan menurut permintaan pasar.
--                      relevance 55.
--
-- Lapis kedua ada supaya tidak ada program studi yang layarnya kosong; lapis
-- pertama supaya "Farmasi" tidak sekadar memunculkan seluruh profesi kesehatan.
-- Semua baris is_verified = false.
--
-- Jalankan setelah 0018. Aman diulang.
-- ============================================================================

begin;

create table if not exists public.education_career (
  source_kind text     not null,
  source_id   integer  not null,
  career_id   integer  not null references public.careers(id) on delete cascade,
  relevance   smallint not null,
  display_order smallint not null,
  source      text     not null,
  is_verified boolean  not null default false,
  primary key (source_kind, source_id, career_id),
  constraint chk_edu_career_kind check (source_kind in ('PRODI','SMK')),
  constraint chk_edu_career_rel  check (relevance between 0 and 100)
);
comment on table public.education_career is
  'Profesi yang relevan dengan satu program studi (source_kind=PRODI, source_id=study_programs.id) atau konsentrasi keahlian SMK (source_kind=SMK, source_id=smk_concentrations.id).';

delete from public.education_career;

