do $$
declare n int;
begin
  select count(*) into n from public.study_programs p
  where not exists (select 1 from public.education_career e
                    where e.source_kind = 'PRODI' and e.source_id = p.id);
  if n > 0 then raise exception '% program studi tidak punya profesi relevan', n; end if;

  select count(*) into n from public.smk_concentrations s
  where not exists (select 1 from public.education_career e
                    where e.source_kind = 'SMK' and e.source_id = s.id);
  if n > 0 then raise exception '% konsentrasi SMK tidak punya profesi relevan', n; end if;
end $$;

alter table public.education_career enable row level security;
drop policy if exists education_career_read_all on public.education_career;
create policy education_career_read_all on public.education_career
  for select to anon, authenticated using (true);

commit;
